class FileSizeUpdater{constructor(){this.logger=new FileSizeLogger}async getLocalFileSize(e){try{if("undefined"!=typeof window&&window.File&&window.FileReader)throw new Error("在浏览器环境中，需要传入 File 对象而不是文件路径");if("undefined"!=typeof require){const t=require("fs");return t.statSync(e).size}throw new Error("不支持的运行环境")}catch(t){throw this.logger.error(`获取本地文件大小失败: ${e}`,t),t}}async getRemoteFileSize(e){try{const t=await fetch(e,{method:"HEAD",headers:{Accept:"*/*"}});if(!t.ok)throw new Error(`HTTP ${t.status}: ${t.statusText}`);const r=t.headers.get("content-length");if(!r)throw new Error("Content-Length 头信息不存在");return parseInt(r,10)}catch(t){throw this.logger.error(`获取远程文件大小失败: ${e}`,t),t}}async getFileSize(e){try{return e.startsWith("http://")||e.startsWith("https://")?await this.getRemoteFileSize(e):await this.getLocalFileSize(e)}catch(t){throw this.logger.error(`获取文件大小失败: ${e}`,t),t}}compareFileSizes(e,t){try{const r={sourceSize:e,targetSize:t,sourceBigger:e>t,targetBigger:t>e,equal:e===t};return this.logger.info(`文件大小比较结果: 源文件 ${e} 字节, 目标文件 ${t} 字节`,r),r}catch(e){throw this.logger.error("文件大小比较失败",e),e}}shouldUpdate(e,t){const r=this.compareFileSizes(e,t).sourceBigger;return this.logger.info("更新决策: "+(r?"执行更新":"不执行更新")),r}async execute(e,t){try{const r=performance.now();this.logger.info(`开始文件大小比较: 源文件 ${e}, 目标文件 ${t}`);const[o,i]=await Promise.all([this.getFileSize(e),this.getFileSize(t)]),s=this.compareFileSizes(o,i),n=this.shouldUpdate(o,i),l=performance.now();return this.logger.info(`文件大小比较完成，耗时 ${(l-r).toFixed(2)}ms`),{shouldUpdate:n,comparison:s}}catch(e){throw this.logger.error("执行文件大小比较失败",e),e}}}class FileSizeLogger{info(e,t=null){const r=`[${(new Date).toISOString()}] [INFO] FileSizeUpdater: ${e}`;t?console.log(r,t):console.log(r)}error(e,t=null){const r=`[${(new Date).toISOString()}] [ERROR] FileSizeUpdater: ${e}`;t?console.error(r,t):console.error(r)}}"undefined"!=typeof module&&module.exports&&(module.exports=FileSizeUpdater,module.exports.FileSizeLogger=FileSizeLogger),"undefined"!=typeof window&&(window.FileSizeUpdater=FileSizeUpdater,window.FileSizeLogger=FileSizeLogger);